def all_pairs(values):
    return [(values[i], values[j]) for i in range(len(values)) for j in range(i + 1, len(values))]

print(all_pairs([1, 2, 3]))

class Node:
    def __init__(self, value, left=None, right=None):
        self.value, self.left, self.right = value, left, right

def inorder(node):
    return inorder(node.left) + [node.value] + inorder(node.right) if node else []

print(inorder(Node(2, Node(1), Node(3))))
